package studio.solocamera;
import android.graphics.*;
/** Fifty profession designs, with authored layouts/palettes and original domain icons. */
final class EditorProfessionTitles {
 static final int FIRST=88,COUNT=50;
 static final String[] DOMAINS={"Technology","Agriculture","Medicine","Education","Business","Finance","Food & hospitality","Beauty & fitness","Construction","Creative media"};
 static final String[][] DESIGNS={{"Quantum circuit","Holo developer","Signal launch","Cyber expert","Future keynote"},{"Green harvest","Living soil","Fresh growth","Field report","Farm to future"},{"Clinical pulse","Care halo","Vital insight","Health expert","Better care"},{"Learning spark","Campus glow","Bright lesson","Knowledge expert","Ideas worth sharing"},{"Executive edge","Vision halo","Impact launch","Strategy expert","Lead the future"},{"Capital pulse","Wealth halo","Market insight","Trusted advisor","Smarter money"},{"Chef signature","Taste halo","Freshly served","Hospitality expert","Stories at the table"},{"Studio glow","Energy halo","Fresh ritual","Wellness expert","Stronger every day"},{"Blueprint edge","Urban halo","Build reveal","Site expert","Build tomorrow"},{"Creator signal","Studio halo","Premiere reveal","Media expert","Lights. Story. Action."}};
 static final int[] PRIMARY={0xff4de8ff,0xff8bf5a5,0xff71e6ed,0xffffcf78,0xff9daeff,0xff66ebc2,0xffffb367,0xffff93d6,0xffffcf57,0xffbc9aff};
 static final int[] SECONDARY={0xffaa75ff,0xffd5f77b,0xff8eb6ff,0xffff927d,0xffffd887,0xffe0d99b,0xffff8179,0xffb59aff,0xffff8c59,0xff69e4ef};
 static boolean profession(int id){return id>=FIRST&&id<FIRST+COUNT;}
 static int domain(int id){return (id-FIRST)/5;}static int variant(int id){return (id-FIRST)%5;}
 static String name(int id){return DOMAINS[domain(id)]+" · "+DESIGNS[domain(id)][variant(id)];}
 static EditorProject.Clip create(int id,long duration){int d=domain(id),v=variant(id);EditorProject.Clip c=new EditorProject.Clip("title:preset",name(id),duration);c.titleDesign=id+1;c.designAccent=PRIMARY[d];c.textBackground=0xff081322;c.textColor=0xfff3f8ff;c.font=v==3?"font:montserrat":v==4?"font:poppins":"font:inter";c.bold=true;c.textSize=v==4?84:58;c.backgroundEnabled=true;c.backgroundRadius=22;c.alignment=0;c.textPlaced=true;c.textY=v==4?0:-.38;c.designEyebrow=DOMAINS[d].toUpperCase(java.util.Locale.US);c.text=v==2||v==3?"YOUR NAME":new String[]{"BUILD WHAT’S NEXT","GROW SOMETHING GREAT","CARE THAT CONNECTS","MAKE LEARNING CLICK","IDEAS INTO IMPACT","MAKE EVERY MOVE COUNT","GOOD FOOD. GREAT STORIES.","MOVE. GLOW. REPEAT.","BUILT WITH PURPOSE","CREATE YOUR NEXT STORY"}[d];c.designSubtitle=new String[]{"Technology • Ideas • Innovation","Farming • Food • Sustainability","Health education • Clear information","Teach • Inspire • Discover","Strategy • People • Progress","Insight • Planning • Confidence","Flavor • Craft • Hospitality","Style • Strength • Wellbeing","Design • Engineering • Craft","Film • Sound • Storytelling"}[d];c.titleGlow=.8;c.titleParticles=true;c.titleSound=true;c.titleSoundVolume=.30;EditorTitlePresets.animate(c,duration,v%3+1);return c;}
 static int[] dimensions(int id,int width,int height){boolean full=variant(id)==4;return new int[]{full?width:Math.max(2,Math.round(width*.86f)),full?height:Math.max(2,Math.min(Math.round(height*.48f),Math.round((variant(id)==1?350:300)*width/1080f)))};}
 static int alpha(int color,int alpha){return (color&0xffffff)|(Math.max(0,Math.min(255,alpha))<<24);}
 static Bitmap bitmap(EditorProject.Clip c,int width,int height){int id=c.titleDesign-1,d=domain(id),v=variant(id);int[] size=dimensions(id,width,height);int w=size[0],h=size[1];float unit=width/1080f,margin=w*.045f;boolean full=v==4,portrait=full&&h>w;int accent=c.designAccent,second=SECONDARY[d];Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas a=new Canvas(b);Paint p=new Paint(3);RectF body=new RectF(full?0:margin*.25f,full?0:h*.05f,full?w:w-margin*.25f,full?h:h*.95f);float radius=Math.max(5,(float)c.backgroundRadius*unit);
  EditorTitleAnimation.begin(a,0);if(c.backgroundEnabled){p.setShader(new LinearGradient(0,0,w,h,new int[]{c.textBackground,blend(c.textBackground,accent,.12f),blend(c.textBackground,second,.14f)},null,Shader.TileMode.CLAMP));if(full)a.drawRect(body,p);else a.drawRoundRect(body,radius,radius,p);p.setShader(null);}p.setColor(alpha(accent,full?25:16));p.setStrokeWidth(Math.max(1,unit));for(int i=1;i<8;i++){float x=w*i/8f;if(v==0||v==3||full)a.drawLine(x,body.top,x,body.bottom,p);}if(v==1||full){p.setShader(new RadialGradient(w*.75f,h*.30f,Math.max(w,h)*.65f,new int[]{alpha(accent,45),alpha(second,12),0},null,Shader.TileMode.CLAMP));a.drawRect(body,p);p.setShader(null);}if(v==3){p.setColor(alpha(second,20));Path slope=new Path();slope.moveTo(w*.74f,body.top);slope.lineTo(w*.93f,body.top);slope.lineTo(w*.72f,body.bottom);slope.lineTo(w*.52f,body.bottom);slope.close();a.drawPath(slope,p);}EditorTitleAnimation.end(a);
  EditorTitleAnimation.begin(a,1);p.setStyle(Paint.Style.STROKE);p.setColor(alpha(accent,180));p.setStrokeWidth(Math.max(1,1.5f*unit));if(c.titleGlow>0)p.setShadowLayer(7*unit*(float)c.titleGlow,0,0,accent);if(!full)a.drawRoundRect(body,radius,radius,p);else{a.drawLine(margin,h*.075f,w-margin,h*.075f,p);a.drawLine(margin,h*.92f,w*.40f,h*.92f,p);}p.clearShadowLayer();p.setStyle(Paint.Style.FILL);
  RectF icon;if(full){float side=portrait?w*.25f:Math.min(w*.25f,h*.43f);icon=new RectF(w*.78f-side/2,h*(portrait?.20f:.43f)-side/2,w*.78f+side/2,h*(portrait?.20f:.43f)+side/2);}else{float side=Math.min(h*(v==1?.64f:.64f),w*.20f);float left=margin*1.35f;icon=new RectF(left,(h-side)/2,left+side,(h+side)/2);}
  p.setColor(alpha(accent,22));float orb=icon.width()*.65f;a.drawCircle(icon.centerX(),icon.centerY(),orb,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(1,unit));p.setColor(alpha(second,135));if(v==1){a.drawCircle(icon.centerX(),icon.centerY(),orb,p);a.drawArc(icon.left-icon.width()*.22f,icon.top-icon.width()*.22f,icon.right+icon.width()*.22f,icon.bottom+icon.width()*.22f,-70,230,false,p);}else if(v==3)a.drawRoundRect(icon.left-8*unit,icon.top-8*unit,icon.right+8*unit,icon.bottom+8*unit,8*unit,8*unit,p);p.setStyle(Paint.Style.FILL);EditorProfessionIcons.draw(a,id-FIRST,icon,accent,(float)c.titleGlow);
  p.setColor(second);if(!full){a.drawRect(margin*1.25f,body.top,w*.32f,body.top+3*unit,p);a.drawRect(w*.77f,body.bottom-3*unit,w-margin,body.bottom,p);}if(c.titleParticles){for(int i=0;i<12;i++){float x=w*(.05f+(i*37%89)/100f),y=h*(.10f+(i*23%73)/100f);if(!full&&x>w*.29f&&x<w*.88f&&y>h*.17f&&y<h*.83f)continue;p.setColor(alpha(i%2==0?accent:second,75));a.drawCircle(x,y,Math.max(.7f,unit*(i%3+1)*.6f),p);}}EditorTitleAnimation.end(a);
  float left=full?margin*1.45f:icon.right+margin*.8f,available=full?(portrait?w-left-margin:w*.61f-left):w-left-margin*1.2f;float top=full?(portrait?h*.40f:h*.28f):h*.33f,mainSize=c.textSize*unit;
  EditorTitleAnimation.begin(a,2);EditorTitleGraphics.draw(a,c,c.designEyebrow,left,full?(portrait?h*.30f:h*.16f):h*.15f,available,Math.max(11*unit,mainSize*.26f),h*.12f,c.font,true,accent,c.alignment);EditorTitleAnimation.end(a);
  EditorTitleAnimation.begin(a,3);float end=EditorTitleGraphics.draw(a,c,c.text,left,top,available,mainSize,full?h*.28f:h*.30f,c.font,c.bold,c.textColor,c.alignment);EditorTitleAnimation.end(a);
  EditorTitleAnimation.begin(a,4);EditorTitleGraphics.draw(a,c,c.designSubtitle,left,Math.max(full?(portrait?h*.70f:h*.65f):h*.69f,end+mainSize*.16f),available,Math.max(12*unit,mainSize*.34f),full?h*.16f:h*.17f,c.font,false,c.textColor,c.alignment);EditorTitleAnimation.end(a);return b;
 }
 static int blend(int a,int b,float amount){return Color.rgb(Math.round(Color.red(a)*(1-amount)+Color.red(b)*amount),Math.round(Color.green(a)*(1-amount)+Color.green(b)*amount),Math.round(Color.blue(a)*(1-amount)+Color.blue(b)*amount));}
}
